import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { frameSubject, turntable } from '../src/studio.js';

describe('frameSubject', () => {
  const cube = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1));
  const { key, fill, rim } = frameSubject(cube);

  const box = new THREE.Box3().setFromObject(cube);
  const sphere = box.getBoundingSphere(new THREE.Sphere());
  const center = sphere.center;
  const r = sphere.radius;

  it('computes the expected Box3 and bounding sphere for a unit cube', () => {
    expect(box.min.equals(new THREE.Vector3(-0.5, -0.5, -0.5))).toBe(true);
    expect(box.max.equals(new THREE.Vector3(0.5, 0.5, 0.5))).toBe(true);
    expect(center.distanceTo(new THREE.Vector3(0, 0, 0))).toBeLessThan(1e-12);
    expect(r).toBeCloseTo(Math.sqrt(3) / 2, 12);
  });

  it('places the key light at 3x the sphere radius from the center', () => {
    expect(key.position.distanceTo(center)).toBeCloseTo(3 * r, 6);
  });

  it('positions the key light at 45 deg elevation / -30 deg azimuth', () => {
    const offset = key.position.clone().sub(center);
    const horizontal = Math.hypot(offset.x, offset.z);
    expect(Math.atan2(offset.y, horizontal)).toBeCloseTo(45 * (Math.PI / 180), 6);
    expect(Math.atan2(offset.x, offset.z)).toBeCloseTo(-30 * (Math.PI / 180), 6);
  });

  it('gives the fill light half of the key intensity', () => {
    expect(fill.intensity).toBeCloseTo(key.intensity / 2, 12);
  });

  it('mirrors the fill light across the key azimuth and matches key distance', () => {
    const fillOffset = fill.position.clone().sub(center);
    expect(Math.atan2(fillOffset.x, fillOffset.z)).toBeCloseTo(30 * (Math.PI / 180), 6);
    expect(fill.position.distanceTo(center)).toBeCloseTo(key.position.distanceTo(center), 6);
  });

  it('places the rim light behind the subject at 1.5x radius', () => {
    expect(rim.position.distanceTo(center)).toBeCloseTo(1.5 * r, 6);
    const rimAzimuth = Math.atan2(
      rim.position.x - center.x,
      rim.position.z - center.z
    );
    expect(rimAzimuth).toBeCloseTo((-30 + 180) * (Math.PI / 180), 6);
  });

  it('targets all lights at the sphere center', () => {
    for (const light of [key, fill, rim]) {
      expect(light.target.position.distanceTo(center)).toBeLessThan(1e-12);
      expect(light.isDirectionalLight).toBe(true);
    }
  });
});

describe('turntable', () => {
  it('sets rotation.y = 0.5 * t (t = 4PI -> 2PI raw value)', () => {
    const subject = new THREE.Object3D();
    turntable(subject, 4 * Math.PI);
    // Raw value, no modulo — 0.5 * 4PI is exactly 2PI in IEEE-754.
    expect(subject.rotation.y).toBeCloseTo(2 * Math.PI, 9);
    expect(subject.rotation.y).toBe(2 * Math.PI);
  });
});

