import * as THREE from 'three';

const DEG = Math.PI / 180;

/**
 * Convert spherical coordinates (elevation/azimuth in degrees) to an
 * offset vector. Elevation is measured up from the horizontal plane,
 * azimuth around the +Y axis starting from +Z.
 */
function sphericalOffset(radius, elevationDeg, azimuthDeg) {
  const el = elevationDeg * DEG;
  const az = azimuthDeg * DEG;
  return new THREE.Vector3(
    radius * Math.cos(el) * Math.sin(az),
    radius * Math.sin(el),
    radius * Math.cos(el) * Math.cos(az)
  );
}

/**
 * Auto-framing three-point light rig.
 *
 * Computes the subject's Box3 and bounding sphere, then returns three
 * DirectionalLights positioned at spherical offsets from the sphere center:
 *   - key:  45 deg elevation / -30 deg azimuth at 3x the bounding radius
 *   - fill: mirrored azimuth (+30 deg) at half the key intensity
 *   - rim:  behind the subject (key azimuth + 180 deg) at 1.5x the radius
 * All lights target the sphere center.
 */
export function frameSubject(subject) {
  const box = new THREE.Box3().setFromObject(subject);
  const sphere = box.getBoundingSphere(new THREE.Sphere());
  const center = sphere.center.clone();
  const r = sphere.radius;

  const makeLight = (radius, elevationDeg, azimuthDeg, intensity) => {
    const light = new THREE.DirectionalLight(0xffffff, intensity);
    light.position.copy(center).add(sphericalOffset(radius, elevationDeg, azimuthDeg));
    light.target.position.copy(center);
    light.target.updateMatrixWorld();
    return light;
  };

  // Key: 3x bounding radius, 45 deg elevation / -30 deg azimuth.
  const key = makeLight(3 * r, 45, -30, 1);

  // Fill: mirrored across azimuth, half the key intensity, same distance.
  const fill = makeLight(3 * r, 45, 30, key.intensity / 2);

  // Rim: behind the subject relative to the key, closer in.
  const rim = makeLight(1.5 * r, 45, -30 + 180, 1);

  return { key, fill, rim };
}

