// Headless end-to-end verification: serve the project over node:http,
// load the page in bundled headless chromium, and assert page behavior
// (never pixels): zero console errors / page errors and #status == "studio-ok".
import http from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json'
};

const server = http.createServer(async (req, res) => {
  try {
    let pathname = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
    if (pathname === '/') pathname = '/public/index.html';
    const filePath = path.normalize(path.join(ROOT, pathname));
    if (!filePath.startsWith(ROOT + path.sep) && filePath !== ROOT) {
      throw new Error('forbidden');
    }
    const data = await readFile(filePath);
    res.writeHead(200, { 'content-type': MIME[path.extname(filePath)] ?? 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404, { 'content-type': 'text/plain' });
    res.end('not found');
  }
});

await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const url = `http://127.0.0.1:${server.address().port}/`;

let exitCode = 0;
try {
  const problems = [];

  const browser = await chromium.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-gpu', '--enable-unsafe-swiftshader']
  });
  const page = await browser.newPage();
  page.on('console', (msg) => {
    if (msg.type() === 'error') problems.push(`console.error: ${msg.text()}`);
  });
  page.on('pageerror', (err) => problems.push(`pageerror: ${err?.message ?? err}`));
  page.on('requestfailed', (req) =>
    problems.push(`requestfailed: ${req.url()} — ${req.failure()?.errorText}`)
  );

  await page.goto(url, { waitUntil: 'load' });
  await page.waitForFunction(
    () => document.getElementById('status')?.textContent === 'studio-ok',
    null,
    { timeout: 15000 }
  );
  const status = await page.locator('#status').textContent();

  await browser.close();

  if (status !== 'studio-ok') {
    problems.push(`#status was "${status}", expected "studio-ok"`);
  }

  if (problems.length > 0) {
    console.error('verify FAILED:');
    for (const p of problems) console.error(`  - ${p}`);
    exitCode = 1;
  } else {
    console.log(`verify OK: no console errors, #status == "studio-ok" at ${url}`);
  }
} catch (err) {
  console.error('verify FAILED:', err?.message ?? err);
  exitCode = 1;
} finally {
  server.close();
}
process.exit(exitCode);

