import { describe, it, expect } from 'vitest';
import { execFileSync } from 'node:child_process';

describe('headless page verification (playwright + chromium)', () => {
  it(
    'scripts/verify.mjs serves the page and finds zero console errors',
    () => {
      const stdout = execFileSync(process.execPath, ['scripts/verify.mjs'], {
        cwd: new URL('..', import.meta.url).pathname,
        encoding: 'utf8',
        timeout: 120_000
      });
      expect(stdout).toContain('verify OK');
      expect(stdout).toContain('studio-ok');
    },
    180_000
  );
});

